/**
 * The prototypes keep applications generated by the pipeline's experiment run out of "your
 * applications". This pins down what that change does and does not touch, on the committed
 * pipeline sample:
 * - the bundle only gains a provenance list (experimentUnitApplicationIds);
 * - application events, experiment specs, assignments, outcomes and upstream analyses are loaded
 *   exactly as before, so no experimental analysis changes;
 * - the production CRM (groupApplications over all events) still contains the generated records,
 *   i.e. the production screens are NOT fixed by this change.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { loadBundle } from "@/adapters";
import { createArtifactSource, type ArtifactReader } from "@/adapters/artifactSource";
import { groupApplications } from "@/lib/applications";
import { splitApplications } from "../../prototypes/lib";

const dir = join(dirname(fileURLToPath(import.meta.url)), "..", "upstream-samples", "pipeline");
const read = (file: string): unknown => {
  try {
    return JSON.parse(readFileSync(join(dir, file), "utf8"));
  } catch {
    return undefined;
  }
};
const reader = (drop: string[] = []): ArtifactReader => ({
  async read(file) {
    return drop.includes(file) ? undefined : read(file);
  },
});

describe("experiment-generated applications (pipeline sample)", () => {
  const expEvents = read("experiment_events.json") as { id: string; application_id: string }[];
  const userEvents = read("events.json") as { id: string; application_id: string }[];
  const generatedIds = [...new Set(expEvents.map((e) => e.application_id))];

  it("are identified by the file they come from, and only those", async () => {
    const b = await loadBundle(createArtifactSource(reader()));
    expect([...b.experimentUnitApplicationIds].sort()).toEqual([...generatedIds].sort());
    for (const e of userEvents) expect(b.experimentUnitApplicationIds).not.toContain(e.application_id);
  });

  it("do not change what is loaded for experiments or applications", async () => {
    const withFile = await loadBundle(createArtifactSource(reader()));
    // Every event from both files is still loaded (ids are unique across the two files in this sample).
    const expectedIds = new Set([...userEvents.map((e) => e.id), ...expEvents.map((e) => e.id)]);
    expect(withFile.applicationEvents.length).toBe(expectedIds.size);
    // Experiment inputs and upstream analyses are untouched by the new field.
    expect(withFile.experiments.length).toBeGreaterThan(0);
    expect(withFile.assignments.length).toBe((read("assignments.json") as unknown[]).length);
    expect(withFile.analyses.length).toBeGreaterThan(0);
    // Analyses are identical whether or not the experiment-events file is present: they never read it.
    const without = await loadBundle(createArtifactSource(reader(["experiment_events.json"])));
    expect(without.analyses).toEqual(withFile.analyses);
    expect(without.assignments).toEqual(withFile.assignments);
    expect(without.experiments).toEqual(withFile.experiments);
  });

  it("are still inside the production CRM data: only the prototypes separate them", async () => {
    const b = await loadBundle(createArtifactSource(reader()));
    const all = groupApplications(b.applicationEvents);
    expect(all.filter((a) => generatedIds.includes(a.id)).length).toBe(generatedIds.length);
    const { mine, generated } = splitApplications(all, b.experimentUnitApplicationIds);
    expect(generated.length).toBe(generatedIds.length);
    expect(mine.every((a) => !generatedIds.includes(a.id))).toBe(true);
  });

  it("is empty when the experiment file is absent (fixture-like sources)", async () => {
    const b = await loadBundle(createArtifactSource(reader(["experiment_events.json"])));
    expect(b.experimentUnitApplicationIds).toEqual([]);
  });
});
